async function(descriptions){
 const x=load("producer_originals_current");if(!load("producer_originals_all_views_returned")||descriptions.length!==x.sources.length)throw Error("Actual source views/descriptions incomplete");
 if(x.views.some(v=>v.alpha_extrema[0]===0))throw Error("This completion helper requires an actually viewed complete painted rectangle, not a genuine exterior cutout");
 const done=(await tools.clock__curr_time({})).current_time.replace(" UTC","Z").replace(" ","T");
 const config={machine_id:"bf-202609141645-5434332d4d",actually_observed:true,observer:"Codex root; same generation executor, original input observation only",allocation:x.allocation,allocation_sha256:x.allocation_sha256,review_started_at_utc:load("producer_originals_view_started").replace(" UTC","Z").replace(" ","T"),review_completed_at_utc:done,mascot_reference_sha256:x.mascot_reference_sha256,mascot_reference_observation:"Exact unchanged mascot reference actually viewed earlier in this same root turn; reused SHA-bound observation, not claimed freshly viewed inside this group interval.",sources:x.sources.map((s,i)=>({key:s.key,description:'Standalone full painted rectangle. '+descriptions[i]})),held:{},viewed_originals:x.views.map(v=>({key:v.key,path:v.path,sha256:v.sha256,size:v.size,alpha_extrema:v.alpha_extrema,actual_native_view:true,nearest_path:v.nearest_path,nearest_sha256:v.nearest_sha256,actual_nearest4_view:true})),scope:"Finite actual original input preparation by existing root generation executor while a/b continue PNG review. No third portrait-review slot, new agent, output approval or image generation. Complete only queues an immutable preparation intent; sole producer rechecks HIGH/service/attempt/input gates."};
 await tools.apply_patch("*** Begin Patch\n*** Add File: C:/workspace/xenoamess_hoi4_dev/"+x.config+"\n+"+JSON.stringify(config,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
 let r=await tools.exec_command({cmd:"python -X utf8 tools\\fresh_source_observation_queue.py complete "+x.config,shell:"cmd.exe",login:false,max_output_tokens:1800});
 let output=r.output||"";store("producer_originals_last_completion_tool",r);
 while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:1800});output+=r.output||"";store("producer_originals_last_completion_tool",r);}
 r={...r,output};
 if(r.exit_code!==0)throw Error(JSON.stringify(r));text(r.output);store("producer_originals_group_completed",x.tag);
}

import json,shutil,subprocess
from datetime import datetime,timezone
from pathlib import Path

root=Path(__file__).resolve().parents[1]
out={'observed_at_utc':datetime.now(timezone.utc).isoformat(),'free_bytes':shutil.disk_usage(root).free,'head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'receipts':[]}
for path in sorted((root/'runtime').glob('checkpoint-resumed-low-*.json')):
    data=json.loads(path.read_text(encoding='utf-8'))
    item={k:data.get(k) for k in ('batch','commit','status','new_original_PNGs','new_original_bytes','original_index_count','pushed_at_utc','remote_original_verification') if k in data}
    if data.get('status') != 'committed_pushed_and_originals_verified':
        item['publish_attempts']=[{k:a[k] for k in ('started_at_utc','completed_at_utc','status','remote_master_after_error') if k in a} for a in data.get('publish_attempt_history',[])]
        if data.get('error'):item['error_tail']=data['error'][-1200:]
    out['receipts'].append(item)
print(json.dumps(out,ensure_ascii=True))
